// Ensure no FT_Face objects remain alive for this library before destroying it
FT_Library lib = *library;
if (!lib) { FUZZ_BAIL(); }
int open_faces = FUZZ_GET_ATTR_INT(lib, "open_faces");
if (open_faces != 0) { FUZZ_BAIL(); }
FT_Error err = FT_Done_FreeType(lib);
if (err != 0) { FUZZ_BAIL(); }
// Validation: Only destroy when tracked open_faces==0; FT_Done_FreeType succeeded.

// Attach auxiliary data (e.g., AFM) from a random file to the face
FT_Face f = *face;
if (!f) { FUZZ_BAIL(); }
const char* path = FUZZ_PARAM_FILENAME();
