if (!f) { FUZZ_BAIL(); }
const char* path = FUZZ_PARAM_FILENAME();
FT_Open_Args args; args.flags = 0; args.memory_base = nullptr; args.memory_size = 0; args.pathname = (FT_String*)path; args.stream = nullptr; args.driver = nullptr; args.num_params = 0; args.params = nullptr;
args.flags = FT_OPEN_PATHNAME;
FT_Error err = FT_Attach_Stream(f, &args);
if (err != 0) { FUZZ_BAIL(); }
// Validation: Attachment via stream succeeded (or bails on failure); face preserved.

// Increment the reference count on the face (library-level refcount)
FT_Face f = *face;
if (!f) { FUZZ_BAIL(); }
FT_Error err = FT_Reference_Face(f);
