// Track external refcount to guard FT_Done_Face stubs
int rc = FUZZ_GET_ATTR_INT(f, "rc");
if (rc <= 0) { rc = 1; }
FUZZ_SET_ATTR_INT(f, "rc", rc + 1);
// Validation: Face remains valid; our tracked rc incremented for later FT_Done_Face checks.

// Enforce our tracked refcount model: only destroy when rc==1
FT_Face f = *face;
if (!f) { FUZZ_BAIL(); }
int rc = FUZZ_GET_ATTR_INT(f, "rc");
if (rc != 1) { FUZZ_BAIL(); }
FT_Library lib = (FT_Library)FUZZ_GET_ATTR_PTR(f, "lib");
FT_Error err = FT_Done_Face(f);
if (err != 0) { FUZZ_BAIL(); }
// Decrement library open face count since this face is destroyed now
if (lib) {
  int open_faces = FUZZ_GET_ATTR_INT(lib, "open_faces");
  FUZZ_SET_ATTR_INT(lib, "open_faces", open_faces - 1);
}
// Validation: Destroy only when tracked rc==1; updates library open_faces accordingly.

// Select a bitmap strike index within available_sizes
FT_Face f = *face;
if (!f) { FUZZ_BAIL(); }
FT_Int count = f->num_fixed_sizes; // relies on public FT_FaceRec fields
if (count <= 0) { FUZZ_BAIL(); }
FT_Int strike_index = (FT_Int)(*FUZZ_PARAM(unsigned int) % (unsigned int)count);
FT_Error err = FT_Select_Size(f, strike_index);
if (err != 0) { FUZZ_BAIL(); }
// Validation: strike_index constrained to [0, num_fixed_sizes-1]; face remains valid.

// Build a reasonable size request
FT_Face f = *face;
if (!f) { FUZZ_BAIL(); }
FT_Size_RequestRec req;
int mode = (int)(*FUZZ_PARAM(unsigned int) % (unsigned int)FT_SIZE_REQUEST_TYPE_MAX);
req.type = (FT_Size_Request_Type)mode;
// Constrain width/height to practical ranges; avoid zeros here
FT_Long w = (FT_Long)((*FUZZ_PARAM(unsigned int) % 256u) + 1);
FT_Long h = (FT_Long)((*FUZZ_PARAM(unsigned int) % 256u) + 1);
if (req.type == FT_SIZE_REQUEST_TYPE_SCALES) {
  // For SCALES, width/height are 16.16; keep modest factors
  req.width  = (w << 10);
  req.height = (h << 10);
} else {
  // For point-based modes, width/height are 26.6
  req.width  = (w << 6);
  req.height = (h << 6);
}
req.horiResolution = (FT_UInt)((*FUZZ_PARAM(unsigned int) % 400u) + 36u); // 36..435 dpi
req.vertResolution = (FT_UInt)((*FUZZ_PARAM(unsigned int) % 400u) + 36u);
FT_Error err = FT_Request_Size(f, &req);
