FT_F26Dot6 ch = (FT_F26Dot6)((((*FUZZ_PARAM(unsigned int)) % 256u) + 1) << 6);
FT_UInt hdpi = (FT_UInt)((*FUZZ_PARAM(unsigned int) % 400u) + 36u);
