import os
import random
from typing import List

# See analysis in previous attempt. Fix: build ASCII bytes via join instead of bytes(generator).

ALNUM = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-"

def _rand_ascii(rng: random.Random, min_len: int, max_len: int) -> bytes:
    n = rng.randint(min_len, max_len)
    return b"".join(rng.choice(ALNUM).encode("ascii") for _ in range(n))


def _u32(rng: random.Random) -> bytes:
    return rng.getrandbits(32).to_bytes(4, "little")


def _make_gradient_block(width: int, height: int) -> bytes:
    block = bytearray(width * height)
    if width == 0 or height == 0:
        return bytes(block)
    for y in range(height):
        for x in range(width):
            v = (x * 255) // max(1, width - 1)
            v = (v + (y * 255) // max(1, height - 1)) // 2
            block[y * width + x] = v & 0xFF
    return bytes(block)


def _make_checker_block(width: int, height: int, cell: int) -> bytes:
    b = bytearray(width * height)
    if width == 0 or height == 0:
        return bytes(b)
    cell = max(1, cell)
    for y in range(height):
        for x in range(width):
            v = 0xAA if ((x // cell) + (y // cell)) % 2 == 0 else 0x20
            b[y * width + x] = v
    return bytes(b)


def _zero_terminated(s: bytes) -> bytes:
    return s + b"\x00"


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    parts: List[bytes] = []

    parts.append(b"FTSEED\x00")

    module_candidates = [
        b"autofitter", b"sfnt", b"psnames", b"type1", b"cff", b"truetype",
        b"smooth", b"raster", b"gzip", b"lzw", b"bzip2"
    ]
    prop_candidates = [
        b"glyph-to-script-map", b"increase-x-height", b"stem-darkening",
        b"lcd-filter-weights", b"random-seed", b"interpreter-version"
    ]

    for _ in range(3):
        parts.append(_zero_terminated(rng.choice(module_candidates)))
    for _ in range(3):
        parts.append(_zero_terminated(rng.choice(prop_candidates)))
    for _ in range(2):
        parts.append(_zero_terminated(_rand_ascii(rng, 3, 16)))
        parts.append(_zero_terminated(_rand_ascii(rng, 3, 16)))

    parts.append(_zero_terminated(_rand_ascii(rng, 8, 32)))

    for _ in range(4):
        parts.append(_u32(rng))

    parts.append(_make_gradient_block(32, 16))
    parts.append(_make_checker_block(24, 24, cell=rng.randint(2, 6)))

    rand_len = rng.randint(256, 768)
    # Python 3.10 Random has no randbytes; fall back to os.urandom
    try:
        rb = rng.randbytes(rand_len)  # type: ignore[attr-defined]
    except AttributeError:
        rb = os.urandom(rand_len)
    parts.append(rb)

    sizes = [(rng.randint(8, 32), rng.randint(8, 32)) for _ in range(3)]
    for w, h in sizes:
        if rng.random() < 0.5:
            parts.append(_make_gradient_block(w, h))
        else:
            parts.append(_make_checker_block(w, h, cell=rng.randint(2, max(2, min(w, h) // 2))))

    for _ in range(2):
        parts.append(_zero_terminated(_rand_ascii(rng, 5, 20)))

    out = b"".join(parts)
    if len(out) > 4096:
        out = out[:4096]
    return out
